public class FuelTank
{
    private int capacity;
    private int fuel;

    public FuelTank(int capacity)
    {
        this.capacity = capacity;
        fuel = capacity;
    }

    public int getFuel()
    {
        return fuel;
    }

    public boolean isEmpty()
    {
        return fuel == 0;
    }

    public void consume(int amount)
    {
        if(amount > 0) {
            fuel = fuel - amount;
            if(fuel < 0) {
                fuel = 0;
            }
        }
    }

    public void refill()
    {
        fuel = capacity;
    }
}

public class ScooterCheck
{
    public static void main(String[] args)
    {
        Scooter fresh = new Scooter("Commuter");
        System.out.println("Default tank: " + fresh.getFuel() + ", running: " + fresh.isRunning());
        fresh.ride(10);
        System.out.println("Ride while stopped: " + fresh.getFuel());
        FuelTank tank = new FuelTank(5);
        Scooter scooter = new Scooter("Runabout", tank);
        scooter.start();
